export const STORAGE_DRIVER = Symbol('StorageDriver');

/**
 * Bytes written but not yet the stored ones. A driver outside the database cannot join the
 * transaction, so the caller settles the write once the unit of work ended.
 */
export interface StagedWrite {
  /** After the commit: the new bytes replace the previous ones. */
  commit(): Promise<void>;
  /** After a rollback: the new bytes go away and the previous ones stay. */
  discard(): Promise<void>;
}

/**
 * Where the bytes of a document are kept. The key is generated by the server (the document id),
 * never taken from the uploaded file name.
 */
export interface StorageDriver {
  /** Writes the bytes without touching the stored ones; runs inside the caller's unit of work. */
  stage(key: string, bytes: Uint8Array): Promise<StagedWrite>;
  /** `null` when nothing is stored under the key. */
  get(key: string): Promise<Uint8Array | null>;
  /** Called after the metadata row was deleted; removing a missing key is not an error. */
  remove(key: string): Promise<void>;
}
